<style>.tt-mel{--blue:#075c7a;--ink:#17313a;--muted:#697a80;--line:#dbe6e9}.tt-mel .hero{padding:1.25rem;border-radius:1rem;color:#fff;background:linear-gradient(120deg,#06465e,#08708e)}.tt-mel .hero h1{margin:.2rem 0;color:#fff;font-size:1.35rem}.tt-mel .hero p{margin:0;color:rgba(255,255,255,.8);font-size:.78rem}.tt-mel .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem;margin:1rem 0}.tt-mel .metric,.tt-mel .panel{border:1px solid var(--line);border-radius:.85rem;background:#fff}.tt-mel .metric{padding:.85rem}.tt-mel .metric small,.tt-mel .metric strong{display:block}.tt-mel .metric small{color:var(--muted);font-size:.62rem;text-transform:uppercase}.tt-mel .metric strong{font-size:1.2rem;color:var(--ink)}.tt-mel .panel{overflow:hidden;margin-bottom:1rem}.tt-mel .head{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 1rem;border-bottom:1px solid var(--line);background:#f7fafb}.tt-mel table{margin:0;font-size:.72rem}.tt-mel th{font-size:.61rem;text-transform:uppercase;background:#f5f8f9}.tt-mel .pill{padding:.23rem .48rem;border-radius:999px;color:#fff;font-size:.61rem;font-weight:800}@media(max-width:800px){.tt-mel .metrics{grid-template-columns:repeat(2,1fr)}}</style>
